args.newString:
def top_words(text, n=3):
    counts = {}
    for w in tokenize(text):
        counts[w] = counts.get(w, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ordered[:n]
